sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?directorBirthDate WHERE {
  VALUES ?film { dbr:The_Stolen_Ranch dbr:The_Father_of_the_Girl }

  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director dbo:birthDate ?birthDate2 . }

  BIND (COALESCE(?birthDate, ?birthDate2) AS ?directorBirthDate)

  FILTER (BOUND(?director) && BOUND(?directorBirthDate))
}
LIMIT 100

